<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="csrf-token" content="{{ csrf_token() }}"><title>Hama IoT | Dashboard</title><script src="https://cdn.jsdelivr.net/npm/chart.js"></script><style>
:root{--bg:#f3f6fb;--ink:#172033;--muted:#718096;--card:#fff;--line:#e7ecf3;--green:#15966b;--yellow:#d28b16;--red:#d64b4b;--nav:#14243a}*{box-sizing:border-box}body{margin:0;background:var(--bg);font:15px Inter,system-ui,Segoe UI,sans-serif;color:var(--ink)}.layout{display:flex;min-height:100vh}.side{width:245px;background:var(--nav);color:#fff;padding:28px 20px}.brand{font-size:19px;font-weight:800;margin-bottom:38px}.brand span{color:#64d6a7}.nav{padding:12px 14px;border-radius:10px;background:#ffffff18;font-weight:600}.side small{display:block;color:#a9b8ca;margin-top:32px;line-height:1.7}.main{flex:1;padding:30px;max-width:1500px;margin:auto;width:100%}.top{display:flex;justify-content:space-between;align-items:center;gap:15px;margin-bottom:24px}.top h1{margin:0;font-size:25px}.sub{color:var(--muted);margin-top:6px}.pill{padding:8px 12px;border-radius:30px;background:#fff;border:1px solid var(--line);font-size:13px}.dot{display:inline-block;width:8px;height:8px;background:#d5a12b;border-radius:50%;margin-right:7px}.grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:16px}.card{background:var(--card);border:1px solid var(--line);border-radius:16px;padding:20px;box-shadow:0 4px 16px #20304a08}.label{font-size:13px;color:var(--muted)}.value{font-size:28px;font-weight:800;margin-top:12px}.hint{font-size:12px;color:var(--muted);margin-top:5px}.section{display:grid;grid-template-columns:1.4fr 1fr;gap:16px;margin-top:18px}.section h3,.controls h3{margin:0 0 18px;font-size:16px}.status{display:inline-block;padding:7px 12px;border-radius:8px;font-size:12px;font-weight:800;background:#edf1f5;color:#5c6675}.AMAN{background:#e5f7ef;color:var(--green)}.WASPADA{background:#fff4dc;color:var(--yellow)}.BAHAYA{background:#ffebeb;color:var(--red)}.sensorline{display:flex;justify-content:space-between;padding:12px 0;border-bottom:1px solid var(--line)}.sensorline:last-child{border:0}.controls{margin-top:18px}.controlgrid{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}.btn{border:0;border-radius:9px;padding:11px 14px;font-weight:700;cursor:pointer;background:#e9eef5;color:#26364b}.btn.primary{background:#1d6b55;color:#fff}.btn.dark{background:#253a55;color:#fff}.btn.warn{background:#fff0d5;color:#94610d}.btn.red{background:#fee8e8;color:#b52e2e}.btn:disabled{opacity:.5;cursor:not-allowed}.row{display:flex;gap:8px;flex-wrap:wrap}.tablewrap{overflow:auto}table{width:100%;border-collapse:collapse;font-size:13px}th,td{text-align:left;padding:11px;border-bottom:1px solid var(--line);white-space:nowrap}th{color:var(--muted);font-weight:600}.foot{font-size:12px;color:var(--muted);margin-top:18px}.toast{margin-top:12px;font-size:13px;color:var(--green)}@media(max-width:1050px){.grid{grid-template-columns:repeat(2,1fr)}.section{grid-template-columns:1fr}}@media(max-width:700px){.side{display:none}.main{padding:18px}.grid{grid-template-columns:1fr 1fr}.controlgrid{grid-template-columns:1fr 1fr}.top{align-items:flex-start;flex-direction:column}}@media(max-width:420px){.grid{grid-template-columns:1fr}}
</style></head><body><div class="layout"><aside class="side"><div class="brand">HAMA<span>GUARD</span></div><div class="nav">▦ &nbsp; Dashboard Monitoring</div><small>SISTEM PENGUSIR HAMA OTOMATIS<br>ESP32 · MQTT · Laravel<br><br>Broker<br>broker.hivemq.com:1883<br><br>Topik status<br>pertanian/hama/status<br><br>Topik kontrol<br>pertanian/hama/kontrol</small></aside><main class="main"><div class="top"><div><h1>Dashboard Monitoring IoT</h1><div class="sub">Pemantauan sensor dan kendali perangkat pengusir hama</div></div><div class="pill"><span class="dot" id="connDot"></span><span id="connection">Menunggu data MQTT</span></div></div>
<div class="grid"><div class="card"><div class="label">Status Deteksi</div><div class="value"><span id="status" class="status">BELUM ADA DATA</span></div><div class="hint">AMAN · WASPADA · BAHAYA</div></div><div class="card"><div class="label">Jarak Objek</div><div class="value"><span id="distance">--</span> <small style="font-size:14px">cm</small></div><div class="hint">Sensor ultrasonik HC-SR04</div></div><div class="card"><div class="label">Gerakan PIR</div><div class="value" id="motion">--</div><div class="hint">GPIO 27</div></div><div class="card"><div class="label">Total Data Masuk</div><div class="value" id="total">0</div><div class="hint">Riwayat tersimpan di database</div></div></div>
<div class="section"><div class="card"><h3>Grafik Jarak Objek</h3><canvas id="distanceChart" height="115"></canvas></div><div class="card"><h3>Kondisi Perangkat</h3><div class="sensorline"><span>Mode operasi</span><b id="mode">--</b></div><div class="sensorline"><span>Alarm / Buzzer</span><b id="alarm">--</b></div><div class="sensorline"><span>LED merah</span><b id="led">--</b></div><div class="sensorline"><span>Keluaran IR</span><b id="ir">--</b></div><div class="sensorline"><span>Lonceng servo</span><b id="bell">--</b></div><div class="sensorline"><span>Buzzer OK</span><b id="buzzerOk">--</b></div><div class="hint" id="lastSeen">Belum menerima data.</div></div></div>
<div class="card controls"><h3>Kontrol Perangkat</h3><p class="label">Perintah dikirim melalui topik pertanian/hama/kontrol. Menekan tombol aktuator akan mengubah sistem ke mode MANUAL.</p><div class="controlgrid"><div><div class="label" style="margin-bottom:8px">Mode operasi</div><div class="row"><button class="btn primary" onclick="sendControl({mode:'AUTO'})">AUTO</button><button class="btn dark" onclick="sendControl({mode:'MANUAL'})">MANUAL</button></div></div><div><div class="label" style="margin-bottom:8px">Buzzer</div><div class="row"><button class="btn warn" onclick="sendControl({buzzer:'ON'})">ON</button><button class="btn" onclick="sendControl({buzzer:'OFF'})">OFF</button></div></div><div><div class="label" style="margin-bottom:8px">LED</div><div class="row"><button class="btn warn" onclick="sendControl({led:'ON'})">ON</button><button class="btn" onclick="sendControl({led:'OFF'})">OFF</button></div></div><div><div class="label" style="margin-bottom:8px">IR</div><div class="row"><button class="btn warn" onclick="sendControl({ir:'ON'})">ON</button><button class="btn" onclick="sendControl({ir:'OFF'})">OFF</button></div></div><div><div class="label" style="margin-bottom:8px">Lonceng Servo</div><div class="row"><button class="btn warn" onclick="sendControl({lonceng:'ON'})">ON</button><button class="btn" onclick="sendControl({lonceng:'OFF'})">OFF</button></div></div></div><div id="toast" class="toast"></div></div>
<div class="card" style="margin-top:18px"><h3>Riwayat Data Terbaru</h3><div class="tablewrap"><table><thead><tr><th>Waktu</th><th>Status</th><th>Gerakan</th><th>Jarak (cm)</th><th>Alarm</th><th>IR</th></tr></thead><tbody id="history"><tr><td colspan="6">Belum ada data masuk. Jalankan listener MQTT.</td></tr></tbody></table></div></div><div class="foot">Refresh data otomatis setiap 2 detik · Laravel backend menyimpan payload MQTT ke database.</div></main></div>
<script>
const csrf=document.querySelector('meta[name="csrf-token"]').content;
const ctx=document.getElementById('distanceChart'); const chart=new Chart(ctx,{type:'line',data:{labels:[],datasets:[{label:'Jarak (cm)',data:[],borderColor:'#1d8b69',backgroundColor:'#1d8b6920',fill:true,tension:.3,spanGaps:true}]},options:{responsive:true,plugins:{legend:{display:false}},scales:{y:{beginAtZero:true,title:{display:true,text:'cm'}}}}});
function val(v){return v===null||v===undefined?'--':v} function onoff(v){return v===null||v===undefined?'--':v}
async function refresh(){try{const r=await fetch('/api/latest',{headers:{'Accept':'application/json'}});if(!r.ok)throw Error('HTTP '+r.status);const d=await r.json();const x=d.latest;if(x){document.getElementById('connection').textContent='Data diterima';document.getElementById('connDot').style.background='#15966b';const s=document.getElementById('status');s.textContent=x.status||'UNKNOWN';s.className='status '+(x.status||'');document.getElementById('distance').textContent=val(x.jarak_cm);document.getElementById('motion').textContent=x.gerakan?'TERDETEKSI':'TIDAK';document.getElementById('mode').textContent=val(x.mode);document.getElementById('alarm').textContent=val(x.alarm);document.getElementById('led').textContent=val(x.payload?.led);document.getElementById('ir').textContent=val(x.ir);document.getElementById('bell').textContent=val(x.lonceng);document.getElementById('buzzerOk').textContent=x.buzzer_ok===null?'--':(x.buzzer_ok?'YA':'TIDAK');document.getElementById('lastSeen').textContent='Data diterima: '+new Date(x.received_at).toLocaleString('id-ID');}else{document.getElementById('connection').textContent='Belum ada pesan';document.getElementById('connDot').style.background='#d5a12b';}document.getElementById('total').textContent=d.total;const rows=d.history||[];document.getElementById('history').innerHTML=rows.slice().reverse().map(a=>`<tr><td>${new Date(a.received_at).toLocaleTimeString('id-ID')}</td><td><span class="status ${a.status}">${a.status}</span></td><td>${a.gerakan?'Ya':'Tidak'}</td><td>${val(a.jarak_cm)}</td><td>${val(a.alarm)}</td><td>${val(a.ir)}</td></tr>`).join('')||'<tr><td colspan="6">Belum ada data.</td></tr>';chart.data.labels=rows.map(a=>new Date(a.received_at).toLocaleTimeString('id-ID'));chart.data.datasets[0].data=rows.map(a=>a.jarak_cm);chart.update('none');}catch(e){document.getElementById('connection').textContent='API tidak terhubung';document.getElementById('connDot').style.background='#d64b4b';}}
async function sendControl(payload){const t=document.getElementById('toast');t.textContent='Mengirim perintah...';try{const r=await fetch('/api/control',{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json','X-CSRF-TOKEN':csrf},body:JSON.stringify(payload)});const d=await r.json();if(!r.ok)throw Error(d.message||'Gagal');t.textContent=d.message+' '+JSON.stringify(d.payload);}catch(e){t.textContent=e.message;}}
refresh();setInterval(refresh,2000);
</script></body></html>
